# Sourced (not executed) by the MySQL image on the very first start, before networking is on.
#
# Two accounts, both TLS-only:
#   securedesk_migrator  DDL on the schema, used by the one-shot `migrate` service only
#   securedesk_app       no rights here; db/mysql/R__grants.sql gives it table-level DML and
#                        nothing but INSERT and SELECT on the audit table (SC-06, SC-09)
# The passwords are hex, generated by the setup step, so they need no quoting.

app_password="$(cat /run/secrets/app-password)"
migrator_password="$(cat /run/secrets/migrator-password)"

docker_process_sql --database=mysql <<-EOSQL
	CREATE DATABASE IF NOT EXISTS securedesk CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
	CREATE USER IF NOT EXISTS 'securedesk_migrator'@'%' IDENTIFIED BY '${migrator_password}' REQUIRE SSL;
	GRANT ALL PRIVILEGES ON securedesk.* TO 'securedesk_migrator'@'%' WITH GRANT OPTION;
	CREATE USER IF NOT EXISTS 'securedesk_app'@'%' IDENTIFIED BY '${app_password}' REQUIRE SSL;
	FLUSH PRIVILEGES;
EOSQL
